// frontend/src/components/MesConges.js
import React, { useState, useEffect } from 'react';
import axios from 'axios';

const MesConges = () => {
  const [conges, setConges] = useState([]);
  const [solde, setSolde] = useState(null);
  const [loading, setLoading] = useState(true);
  const [formData, setFormData] = useState({
    type_conge: 'conges_payes',
    date_debut: '',
    date_fin: '',
    motif: ''
  });

  const token = localStorage.getItem('token');

  // Charger mes congés
  useEffect(() => {
    fetchMesConges();
  }, []);

  const fetchMesConges = async () => {
    try {
      const response = await axios.get('http://localhost:5000/api/conges/mes-conges', {
        headers: { Authorization: `Bearer ${token}` }
      });
      setConges(response.data.conges);
      setSolde(response.data.solde);
    } catch (err) {
      console.error('Erreur:', err);
    } finally {
      setLoading(false);
    }
  };

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      await axios.post('http://localhost:5000/api/conges', formData, {
        headers: { Authorization: `Bearer ${token}` }
      });
      alert('Demande envoyée !');
      setFormData({ type_conge: 'conges_payes', date_debut: '', date_fin: '', motif: '' });
      fetchMesConges();
    } catch (err) {
      alert(err.response?.data?.message || 'Erreur');
    }
  };

  // Formater la date
  const formatDate = (date) => new Date(date).toLocaleDateString('fr-FR');

  // Status badge
  const StatusBadge = ({ statut }) => {
    const styles = {
      en_attente: 'badge bg-warning text-dark',
      approuve: 'badge bg-success',
      refuse: 'badge bg-danger',
      annule: 'badge bg-secondary'
    };
    const texts = {
      en_attente: 'En attente',
      approuve: 'Approuvé',
      refuse: 'Refusé',
      annule: 'Annulé'
    };
    return <span className={styles[statut]}>{texts[statut]}</span>;
  };

  if (loading) return <div className="text-center mt-5">Chargement...</div>;

  return (
    <div className="container mt-4">
      <div className="row">
        {/* Solde Card */}
        <div className="col-md-4 mb-4">
          <div className="card bg-primary text-white">
            <div className="card-body">
              <h5 className="card-title">Mon Solde</h5>
              <h2 className="display-4">{solde?.conges_payes || 0} jours</h2>
              <p className="mb-0">Congés restants • Année {solde?.annee}</p>
            </div>
          </div>
        </div>

        {/* Formulaire */}
        <div className="col-md-8 mb-4">
          <div className="card">
            <div className="card-header bg-success text-white">
              <h5 className="mb-0">📅 Demander un congé</h5>
            </div>
            <div className="card-body">
              <form onSubmit={handleSubmit}>
                <div className="row">
                  <div className="col-md-4 mb-3">
                    <label className="form-label">Type</label>
                    <select name="type_conge" className="form-select" value={formData.type_conge} onChange={handleChange} required>
                      <option value="conges_payes">Congés payés</option>
                      <option value="rtt">RTT</option>
                      <option value="maladie">Congé maladie</option>
                    </select>
                  </div>
                  <div className="col-md-4 mb-3">
                    <label className="form-label">Date début</label>
                    <input type="date" name="date_debut" className="form-control" value={formData.date_debut} onChange={handleChange} required />
                  </div>
                  <div className="col-md-4 mb-3">
                    <label className="form-label">Date fin</label>
                    <input type="date" name="date_fin" className="form-control" value={formData.date_fin} onChange={handleChange} required />
                  </div>
                  <div className="col-md-12 mb-3">
                    <label className="form-label">Motif (optionnel)</label>
                    <textarea name="motif" className="form-control" rows="2" value={formData.motif} onChange={handleChange} placeholder="Raison du congé..."></textarea>
                  </div>
                  <div className="col-md-12">
                    <button type="submit" className="btn btn-success">📤 Envoyer la demande</button>
                  </div>
                </div>
              </form>
            </div>
          </div>
        </div>
      </div>

      {/* Liste des demandes */}
      <div className="card">
        <div className="card-header bg-info text-white">
          <h5 className="mb-0">📋 Mes demandes de congés</h5>
        </div>
        <div className="card-body">
          {conges.length === 0 ? (
            <p className="text-muted">Aucune demande de congé</p>
          ) : (
            <div className="table-responsive">
              <table className="table table-hover">
                <thead>
                  <tr>
                    <th>ID</th>
                    <th>Type</th>
                    <th>Du</th>
                    <th>Au</th>
                    <th>Jours</th>
                    <th>Statut</th>
                    <th>Motif</th>
                  </tr>
                </thead>
                <tbody>
                  {conges.map((conge) => (
                    <tr key={conge.id}>
                      <td>{conge.id}</td>
                      <td>{conge.type_conge === 'conges_payes' ? '🏖️ Congés payés' : conge.type_conge === 'rtt' ? '⚡ RTT' : '🤒 Congé maladie'}</td>
                      <td>{formatDate(conge.date_debut)}</td>
                      <td>{formatDate(conge.date_fin)}</td>
                      <td>{conge.nombre_jours_reels}</td>
                      <td><StatusBadge statut={conge.statut} /></td>
                      <td>{conge.motif || '-'}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default MesConges;
